// Runs in n8n's Code node, once for all input items.
const results = $input.all();
return results.map((item, index) => {
  const response = item.json;
  if (response.statusCode !== 200) {
    throw new Error(`Factur-X returned HTTP ${response.statusCode ?? 'unknown'}. Check access, quota or input. No automatic retry was made.`);
  }
  const result = response.body;
  if (!result || result.output !== 'facturx-pdf' || result.profile !== 'en16931' ||
      result.media_type !== 'application/pdf' || typeof result.content_base64 !== 'string') {
    throw new Error('Unexpected Factur-X response; no PDF released.');
  }
  const check = result.validation;
  const required = ['xsd', 'schematron:base', 'schematron:fr-ctc'];
  if (!check || check.valid !== true || check.error_count !== 0 ||
      !Array.isArray(check.checks_skipped) || check.checks_skipped.length ||
      !Array.isArray(check.checks_run) || !required.every(name => check.checks_run.includes(name))) {
    throw new Error('Invoice validation failed or required checks were missing/skipped; no PDF released.');
  }
  const pdf = Buffer.from(result.content_base64, 'base64');
  if (pdf.toString('base64') !== result.content_base64 || pdf.subarray(0, 5).toString('ascii') !== '%PDF-') {
    throw new Error('Invalid PDF payload; no PDF released.');
  }
  const { content_base64, ...report } = result;
  return { json: { content_base64, report }, pairedItem: { item: index } };
});
